+package release
+
+import (
+	"context"
+	"net/http"
+	"net/http/httptest"
+	"net/url"
+	"testing"
+
+	"github.com/google/go-github/v32/github"
+)
+
+func TestIs(t *testing.T) {
+	tests := []struct {
+		version string
+		want    bool
+	}{
+		{"", false},
+		{"dev", false},
+		{"1.2.3-dev", false},
+		{"1.2.3-snapshot", false},
+		{"1.2.3-rc", false},
+		{"1.2.3-rc.1", false},
+		{"v1.2.3", true},
+		{"1.2.3+build", true},
+	}
+	for _, tt := range tests {
+		t.Run(tt.version, func(t *testing.T) {
+			if got := Is(tt.version); got != tt.want {
+				t.Fatalf("Is(%q) = %t, want %t", tt.version, got, tt.want)
+			}
+		})
+	}
+}
+
+func TestCheck(t *testing.T) {
+	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		if r.URL.Path != "/repos/flipt-io/flipt/releases/latest" {
+			t.Errorf("unexpected path: %s", r.URL.Path)
+		}
+		w.Header().Set("Content-Type", "application/json")
+		_, _ = w.Write([]byte(`{"tag_name":"v1.3.0","html_url":"https://example.com/v1.3.0"}`))
+	}))
+	defer server.Close()
+
+	client := github.NewClient(server.Client())
+	baseURL, err := url.Parse(server.URL + "/")
+	if err != nil {
+		t.Fatal(err)
+	}
+	client.BaseURL = baseURL
+
+	for _, tt := range []struct {
+		current string
+		update  bool
+	}{
+		{"v1.2.0", true},
+		{"v1.3.0", false},
+		{"v1.4.0", false},
+	} {
+		got, err := check(context.Background(), tt.current, client)
+		if err != nil {
+			t.Fatal(err)
+		}
+		if got.CurrentVersion != tt.current || got.LatestVersion != "v1.3.0" || got.LatestVersionURL != "https://example.com/v1.3.0" || got.UpdateAvailable != tt.update {
+			t.Fatalf("check(%q) = %+v", tt.current, got)
+		}
+	}
+}
+
+func TestCheckFailureRetainsCurrentVersion(t *testing.T) {
+	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
+		http.Error(w, "unavailable", http.StatusServiceUnavailable)
+	}))
+	defer server.Close()
+
+	client := github.NewClient(server.Client())
+	baseURL, err := url.Parse(server.URL + "/")
+	if err != nil {
+		t.Fatal(err)
+	}
+	client.BaseURL = baseURL
+
+	got, err := check(context.Background(), "v1.2.0", client)
+	if err == nil {
+		t.Fatal("expected update check error")
+	}
+	if got.CurrentVersion != "v1.2.0" || got.LatestVersion != "" || got.UpdateAvailable {
+		t.Fatalf("check failure returned %+v", got)
+	}
+}
